NAVY='17365D'; TEAL='168C8C'; GOLD='C47F17'; MUTED='5B6573'

def shade(cell,fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=OxmlElement('w:shd'); shd.set(qn('w:fill'),fill); tcPr.append(shd)

def page_field(paragraph):
    run=paragraph.add_run(); fld=OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE'); run._r.addnext(fld)

def style_doc(doc,kind):
    sec=doc.sections[0]; sec.top_margin=Inches(.7);sec.bottom_margin=Inches(.65);sec.left_margin=Inches(.8);sec.right_margin=Inches(.8)
    normal=doc.styles['Normal'];normal.font.name='Aptos';normal.font.size=Pt(10);normal.font.color.rgb=RGBColor.from_string('263238');normal.paragraph_format.space_after=Pt(6)
    for name,size,color in [('Title',30,NAVY),('Heading 1',19,NAVY),('Heading 2',13,TEAL),('Heading 3',11,NAVY)]:
        st=doc.styles[name];st.font.name='Aptos Display';st.font.size=Pt(size);st.font.bold=True;st.font.color.rgb=RGBColor.from_string(color)
    footer=sec.footer.paragraphs[0];footer.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    footer.add_run('ZilaLens | Kanishk Gupta     ');page_field(footer)
    props=doc.core_properties;props.author=AUTHOR;props.title=f'{TITLE} — {kind}';props.subject=SUB;props.keywords='NFHS-4, NFHS-5, district, financial inclusion'

def add_title(doc,tag=None):
    p=doc.add_paragraph();p.style='Title';p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run(TITLE)
    p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;r=p.add_run(SUB);r.bold=True;r.font.size=Pt(15);r.font.color.rgb=RGBColor.from_string(TEAL)
    p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;r=p.add_run(AUTHOR);r.bold=True;r.font.size=Pt(12)
    p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.add_run(GITHUB).font.color.rgb=RGBColor.from_string(TEAL)
    if tag:
        p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER;r=p.add_run(tag.upper());r.bold=True;r.font.color.rgb=RGBColor.from_string(GOLD)

def bullet(doc,text): doc.add_paragraph(text,style='List Bullet')
def table(doc,headers,rows,widths=None):
    t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.style='Light Shading Accent 1'
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i];c.text=h;shade(c,NAVY)
        for r in c.paragraphs[0].runs:r.font.bold=True;r.font.color.rgb=RGBColor(255,255,255);r.font.size=Pt(9)
    for row in rows:
        cells=t.add_row().cells
        for i,val in enumerate(row):cells[i].text=str(val);cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.TOP
    for row in t.rows:
        for c in row.cells:
            for p in c.paragraphs:
                p.paragraph_format.space_after=Pt(2)
                for r in p.runs:r.font.size=Pt(8.5)
    return t

def report():
    d=Document();style_doc(d,'Research Report');add_title(d,'Descriptive findings | 18 October 2026');d.add_paragraph('Descriptive analysis • 18 October 2026',style='Subtitle');d.add_paragraph('This report presents descriptive district comparisons from NFHS-4 and NFHS-5, with explicit screens for changed geography and incompatible indicators.',style='Intense Quote');d.add_page_break()
    d.add_heading('Contents',0)
    for x in ['Executive summary','Background and research questions','Data and methods','District harmonisation and quality','RQ1 Change in financial inclusion','RQ2 Fast improvers and district typologies','RQ3 Aspirational Districts comparison','RQ4 Uttar Pradesh deep dive','RQ5 Policy evidence','Discussion and recommendations','Limitations','References','Annexes']:bullet(d,x)
    d.add_page_break()
    pages=[
    ('Executive summary',['ZilaLens compares women’s financial inclusion and related empowerment indicators across Indian districts between NFHS-4 (2015-16) and NFHS-5 (2019-21). “Zila” means district in Hindi; the project views women’s financial inclusion through a district lens.','The NFHS-4 source contains 59,241 district-indicator rows, and the NFHS-5 workbook contains 75,649 rows. (Sources: data/raw/nfhs_district-wise.csv; data/raw/NFHS_5_India_Districts_Factsheet_Data.xls.)','The user supplied the official NFHS-5 workbook. Four comparable indicators were analyzed. Across 555 name-matched districts, literacy rose 6.5 percentage points on average, schooling 6.3 points, clean cooking fuel 15.9 points, and marriage before age 18 fell 3.8 points. (Source: outputs/tables/district_changes.csv; n=555 per indicator.)','The descriptive Aspirational District contrast is mixed: the cohort showed a 1.99 pp larger literacy increase (95% bootstrap interval 0.76 to 3.14), while differences for the other three indicators include zero. These are associations, not causal effects. (Source: outputs/tables/aspirational_comparison.csv; matched n=388 overall.)','The requested bank-account-use and mobile-phone indicators are absent from both factsheet sources, so the finance-linked index is unavailable. The four-indicator cluster typology and NFHS-5 UP descriptive rankings are provided separately. (Source: data_quality_report.md; outputs/tables/analysis_status.md.)']),
    ('Background and research questions',['Women’s bank account ownership does not by itself establish active use, control over transactions, or the ability to use digital services safely. The proposed comparison focuses on indicators that are present in both NFHS rounds and retains their source definitions.','The research questions cover district change, fast improvers and lagging districts, descriptive differences between Aspirational and comparable non-aspirational districts, Uttar Pradesh district patterns, and policy drivers and barriers.','NFHS district estimates are survey estimates. District boundaries and names changed between rounds, so comparisons require an explicit crosswalk. This interim report distinguishes direct source observations, computed project status, and unanswered questions.']),
    ('Data and methods',['NFHS-4 district factsheet data were downloaded from HindustanTimesLabs/nfhs-data. The source file contains district, state, census codes, total/rural/urban estimates, indicator number, indicator name, and category. (Source: data/raw/nfhs_district-wise.csv.)','The user supplied the official NFHS-5 workbook on 18 October 2026; it is stored at data/raw/NFHS_5_India_Districts_Factsheet_Data.xls. The catalog direct URL returned HTTP 403; provenance is recorded in docs/DATA_SOURCES.md.','The pipeline harmonizes state/district labels and screens the 130 changed/new geographies listed in Harvard Appendix A. The appendix does not specify every parent, so those observations are excluded rather than imputed. The remaining 555 matches are normalized-name candidates, not proof of identical boundaries. (Source: data/processed/harvard_changed_geographies.csv; data/processed/district_crosswalk.csv.)','Changes are reported in percentage points and relative percent change. The financial index and its sensitivity analysis are withheld because no bank/mobile indicator is present. The descriptive typology uses baseline levels and changes in four common indicators; Aspirational comparisons use bootstrap intervals and are non-causal. (Source: outputs/tables/district_changes.csv; analysis_status.md.)']),
    ('District harmonisation and data quality',['The NFHS-4 file has 59,241 district-indicator rows and 93 district-level indicators according to its source README. The parsed panel currently contains NFHS-4 only. (Source: HindustanTimesLabs/nfhs-data, README.md and nfhs_district-wise.csv.)','The crosswalk screens 130 changed/new geography entries from Harvard Appendix A. The remaining 555 directly matched district-name candidates are present in both rounds. The NITI 112-district roster retains unresolved matches as unknown. (Sources: data/processed/district_crosswalk.csv; data/processed/harvard_changed_geographies.csv; data/processed/aspirational_districts_112.csv.)','The current GeoJSON contains 645 features. Baseline maps join 563 NFHS-4 district estimates by normalized district and state name. (Source: data/raw/india_districts.geojson; map join counts in figure notes.) This geography is illustrative and not confirmed as boundary-equivalent to the survey rounds.']),
    ('RQ1 Change in financial inclusion',['Across 555 screened matches, the four paired indicators changed by the following average percentage points: women’s literacy +6.5; schooling +6.3; marriage before age 18 −3.8; clean cooking fuel +15.9. Each indicator has a distinct valid n=555. (Source: outputs/tables/district_changes.csv.)','The four comparable indicators are women’s literacy, schooling (10+ years), marriage before age 18, and clean cooking fuel. Sanitation is excluded because the rounds use different denominators. Bank-account-use and mobile-phone measures are absent in both source files. (Sources: data/raw/nfhs_district-wise.csv; NFHS_5_India_Districts_Factsheet_Data.xls.)','District changes and state summaries are in outputs/tables/district_changes.csv and change_state_summary.csv. They are descriptive survey estimate differences and should not be interpreted as causal programme effects.']),
    ('RQ2 Fast improvers and typologies',['The screened paired file contains 2,220 district-indicator changes (555 districts × four indicators). Top and bottom 20 tables are in outputs/tables/district_rankings.csv. The four-indicator baseline-plus-change typology uses silhouette-selected k; see outputs/tables/district_clusters.csv and analysis_status.md.','Each district change is calculated as NFHS-5 minus NFHS-4 in percentage points and relative percent. The typology clusters four baseline levels and their changes; it does not use account-use or phone indicators.','The clusters are descriptive and should not be called financial inclusion typologies because account-use and mobile-use indicators are unavailable.']),
    ('RQ3 Aspirational Districts comparison',['The requested design is a descriptive difference-in-differences comparison, not a causal evaluation. The analysis reports average changes for Aspirational Districts and other districts, a baseline-bottom-quartile comparison, and bootstrap intervals.','The NITI Aayog PDF provides the requested 112-district roster. It was published in 2022 and is used here as the project’s specified cohort. The exact-match roster coverage is 96 of 112 NFHS-4 district names; unmatched names require boundary and naming review. (Sources: data/raw/docs/aspirational_112.pdf; data/processed/aspirational_districts_112.csv.)','The 8 reported contrasts cover four indicators and two comparison groups. For the all-district literacy comparison, the Aspirational cohort change exceeded the comparison group by 1.99 pp (95% bootstrap interval 0.76 to 3.14; n=94 versus 294). The baseline-bottom-quartile contrast was −0.04 pp (interval −1.67 to 1.54; n=53 versus 45). Estimates are descriptive; roster mapping gaps and selection bias limit comparability. (Source: outputs/tables/aspirational_comparison.csv.)']),
    ('RQ4 Uttar Pradesh deep dive',['All 75 Uttar Pradesh districts are ranked on a mean rank across NFHS-5 literacy, schooling, early marriage (reversed), and clean-fuel levels. Ghaziabad ranks 1 and Gautam Buddha Nagar ranks 6 on this descriptive composite. The five lowest ranked are Shrawasti, Lalitpur, Bahraich, Balrampur, and Sitapur. This is not a financial inclusion index. (Source: outputs/tables/up_district_rankings.csv.)','NFHS-4 maps provide baseline context. The separate UP ranking table shows all districts and the two requested callouts. The public boundary file is from a different vintage; maps are illustrative and are not used to calculate the rankings.','The UP cross-section includes all 75 NFHS-5 district records. Changed geography may still affect comparison with NFHS-4, so the level ranking is kept separate from matched change estimates.']),
    ('RQ5 Public policy evidence',['The review covers the PMJDY Mission Document/Brochure and the NITI Aayog/UNDP Aspirational Districts Programme appraisal. Seven paraphrased passages with physical page references are recorded in the coding workbook.','The PMJDY brochure describes expansion of branches and Bank Mitra service points (physical p. 18), transaction interoperability and access (p. 20), and unreliable telecom networks in tribal and hilly areas (p. 30). These are policy design statements, not district outcome estimates.','The ADP appraisal discusses district technical and administrative capacity (physical p. 15), the programme’s convergence, collaboration and competition model (p. 20), and its use of pre-pandemic observations in its own analysis (p. 28). (Sources: data/raw/docs/pmjdy_brochure.pdf; data/raw/docs/adp_appraisal.pdf.)']),
    ('Discussion and recommendations',['The available sources point to a useful distinction between access infrastructure and actual use. The proposed field instrument asks about personal account use, transaction frequency, decision control, phone access, service reliability, and support needs.','For programme planning, first confirm the district-level pattern; then validate whether low reported use reflects account access, service reliability, skills, safety, or household decision constraints. Avoid selecting districts from a name-only comparison.','Build the final intervention around local service mapping, practical assisted account use, digital safety, grievance referral, and routine monitoring. Treat these as design options pending district validation, not proven effects.']),
    ('Limitations',['Indicator coverage: requested bank-account-use and mobile-phone measures are absent from both factsheet sources. Index construction and finance-specific RQs remain unanswered by these data.','Aspirational District selection: districts were selected because of pre-existing deprivation and differ from other districts. Descriptive differences and baseline matching cannot remove all selection bias; results will not be interpreted causally.','Boundary changes: Harvard Appendix A lists 130 changed/new NFHS-5 geography entries. Because the available appendix does not list all parent districts, affected areas are excluded; normalized-name matches elsewhere still need boundary validation.','Survey sampling error: district estimates are subject to sampling variability. The available factsheet estimates do not provide a complete basis for conventional significance testing of all district changes.','NFHS-5 fieldwork occurred during the COVID-19 period (2019-21), which may affect timing and interpretation. Policy documents also reflect their publication period and do not measure current local service quality.']),
    ('References',['International Institute for Population Sciences (IIPS) and Ministry of Health and Family Welfare (MoHFW). National Family Health Survey-4 district factsheet data, 2015-16. Dataset compilation by HindustanTimesLabs, data/raw/nfhs_district-wise.csv; https://github.com/HindustanTimesLabs/nfhs-data.','NITI Aayog. List of 112 Aspirational Districts. 2022. data/raw/docs/aspirational_112.pdf; https://www.niti.gov.in/sites/default/files/2022-09/List-of-Aspirational-Districts.pdf.','Department of Financial Services, Ministry of Finance. PMJDY Mission Document/Brochure. data/raw/docs/pmjdy_brochure.pdf; https://pmjdy.gov.in/files/E-Documents/PMJDY_BROCHURE_ENG.pdf.','NITI Aayog and United Nations Development Programme. Aspirational Districts Programme: An Appraisal. data/raw/docs/adp_appraisal.pdf; https://www.niti.gov.in/sites/default/files/2023-03/Aspirational-Districts-Programme-An-Appraisal.pdf.','Harvard Geographic Insights Lab. NFHS Policy Tracker for Districts: User Guide and Technical Notes, 7 February 2022. Appendix A (changed/new district list). Archived PDF: data/raw/docs/harvard_nfhs_policy_tracker_technical_notes.pdf; source page: https://geographicinsights.iq.harvard.edu/.' ,'HindustanTimesLabs. India district boundaries GeoJSON. data/raw/india_districts.geojson; https://github.com/HindustanTimesLabs/shapefiles/tree/master/india.']),
    ('Annexes',['Crosswalk method: normalized exact names form provisional identifiers. Candidate fuzzy matches are suggestions only. Every approved name or parent/child mapping must be written to data/processed/district_name_overrides.csv and documented in data/processed/district_crosswalk.csv.','Indicator definitions available in NFHS-4 include “Women who are literate (%)”, “Women with 10 or more years of schooling (%)”, “Women age 20-24 years married before age 18 years (%)”, “Households using clean fuel for cooking”, and “Households using improved sanitation facility”. (Source: data/raw/nfhs_district-wise.csv.)','The logframe, theory of change, bilingual field tool, and sampling plan are included as separate editable outputs. Baselines and targets that depend on selected districts are labeled pending.'])]
    for idx,(heading,paragraphs) in enumerate(pages):
        d.add_heading(heading,0 if idx==0 else 1)
        for para in paragraphs:d.add_paragraph(para)
        if heading.startswith('RQ4'):
            d.add_picture(str(ROOT/'outputs'/'maps'/'women_literate_nfhs4.png'),width=Inches(5.6)); cap=d.add_paragraph('Figure 1. NFHS-4 women literacy baseline by district. Source and n are stated on the map.');cap.alignment=WD_ALIGN_PARAGRAPH.CENTER
        if heading.startswith('Annexes'):
            d.add_paragraph('Table 1. Core source indicator definitions currently identified in NFHS-4. Source: HindustanTimesLabs nfhs_district-wise.csv.')
            table(d,['Indicator','NFHS-4 source name','Round status'],[['Literacy','Women who are literate (%)','Comparable definition used'],['Schooling','Women with 10 or more years of schooling (%)','Comparable definition used'],['Early marriage','Women age 20-24 years married before age 18 years (%)','Comparable definition used'],['Cooking fuel','Households using clean fuel for cooking','Comparable definition used'],['Sanitation','Households using improved sanitation facility','Comparable definition used']])
        if idx<len(pages)-1:d.add_page_break()
    path=ROOT/'outputs'/'reports'/'ZilaLens_Research_Report.docx';d.save(path);return path

def concept_note():
    d=Document();style_doc(d,'Concept Note');add_title(d,'Concept note draft | provisional UP districts identified');d.add_paragraph('Proposed 12-month CSR or donor-funded pilot in Shrawasti, Lalitpur, Bahraich, Balrampur and Sitapur, subject to field validation and boundary review. These are the five lowest-ranked districts on a four-indicator NFHS-5 descriptive composite, not a finance index.');d.add_page_break()
    d.add_heading('1. Problem and rationale',1);d.add_paragraph('Public financial inclusion programmes have expanded formal access, while a woman’s account ownership does not by itself show whether she can use the account regularly, privately, and with control over transactions. ZilaLens proposes a district-focused pilot that will pair quantitative district evidence with field validation before final geographies are chosen. The project name combines “Zila”, Hindi for district, with a district lens on women’s financial inclusion.')
    d.add_paragraph('The NFHS-4 factsheet compilation contains 59,241 district-indicator rows; the user-supplied NFHS-5 workbook contributes 75,649 rows. In the NFHS-5 four-indicator mean-rank composite, the five lowest-ranked Uttar Pradesh districts are Shrawasti, Lalitpur, Bahraich, Balrampur and Sitapur. These are provisional planning candidates; field validation, local partner capacity and boundary review must inform final selection. (Sources: data/raw/nfhs_district-wise.csv; data/raw/NFHS_5_India_Districts_Factsheet_Data.xls; outputs/tables/up_district_rankings.csv.)')
    d.add_heading('2. Goal and objectives',1);bullet(d,'Goal: support women to access and use suitable financial services as part of stronger livelihood resilience.')
    bullet(d,'Objective 1: identify local account ownership, use, control, phone access, and service barriers through district data and field validation.')
    bullet(d,'Objective 2: improve practical use, digital safety, and access to responsive service points in selected districts.')
    bullet(d,'Objective 3: build a simple monitoring system that tracks women’s independent use and service quality, not enrolment alone.')
    d.add_heading('3. Intervention and results framework',1);table(d,['Workstream','Activities','Proposed measures'],[['Local service access','Map banks/BC points, hours, network, grievance route','Functional service points; issue resolution'],['Women’s financial capability','Small-group practice on balances, deposits, withdrawals, transfers and safety','Independent task completion; knowledge check'],['Peer and referral support','Train local resource persons; refer service failures and fraud concerns','Referral completion; participant feedback'],['Monitoring and learning','Baseline, quarterly checks, endline and adaptation','Account use, control and satisfaction measures']])
    d.add_page_break();d.add_heading('4. Implementation approach',1);d.add_paragraph('A local implementation partner would work with district administration, banks, BC networks, women’s collectives, and community organizations. The first two months would confirm district selection, partner capacity, safeguarding, and a service-point map. Months 3–9 would deliver community sessions and assisted practice. Months 10–12 would consolidate referrals, repeat measures, and document adaptations. No direct account opening targets should replace informed choice or service quality.')
    d.add_heading('5. Indicative budget',1);d.add_paragraph('Planning assumption: 4 districts for 12 months; values below are illustrative estimates in Indian rupees and require local costing and donor approval.')
    table(d,['Cost line','Calculation assumption','Indicative amount (₹ lakh)'],[['District facilitators','8 facilitators × 12 months × ₹45,000/month','43.2'],['Training and materials','40 sessions × ₹35,000','14.0'],['Travel and field supervision','4 districts × ₹2.5 lakh/month × 12 months','120.0'],['Baseline and endline','Survey design, fieldwork, analysis','35.0'],['Digital safety and referral support','Materials, helpdesk linkage, escalation','12.0'],['Programme management and audit','Central coordination, safeguarding, audit','24.0'],['Subtotal','','248.2'],['Contingency','5% of subtotal; planning assumption','12.4'],['Total','','260.6']])
    d.add_heading('6. Risks and mitigation',1);table(d,['Risk','Mitigation'],[['Composite omits financial inclusion measures','Use the ranking only for initial screening; collect account-use and mobile-use evidence before final selection.'],['Women’s account-use interviews lack privacy','Use trained women enumerators, consent, private interviews and skip options.'],['BC/service point gaps or network outages','Map service availability; coordinate escalation with bank and telecom partners.'],['Digital fraud or harm','Teach safety, avoid requesting credentials, and provide verified reporting channels.'],['Programme measures reward account opening only','Track active use, control, problem resolution and participant experience.']])
    d.add_page_break();d.add_heading('7. Monitoring, evaluation and learning',1);d.add_paragraph('The attached logframe identifies outcome and service measures. Numeric baselines and targets will be set after district selection, sample design and power considerations. The proposed field tool validates independent account use and the gap between access and use. Pre/post comparisons would describe programme-associated change only; stronger causal claims would require a separately designed evaluation.')
    d.add_heading('8. SDG alignment',1);bullet(d,'SDG 1: strengthen household capacity to manage financial shocks.');bullet(d,'SDG 5: support women’s agency and control over financial decisions.');bullet(d,'SDG 8: improve access to useful financial services that can support livelihoods.');bullet(d,'SDG 10: prioritize underserved districts and monitor unequal access.')
    d.add_paragraph('Prepared by Kanishk Gupta | PGDM (Research & Business Analytics), Lal Bahadur Shastri Institute of Management, Delhi | '+GITHUB)
    p=ROOT/'outputs'/'reports'/'ZilaLens_Concept_Note.docx';d.save(p);return p

def policy_brief():
    d=Document();style_doc(d,'Policy Brief');sec=d.sections[0];sec.top_margin=Inches(.45);sec.bottom_margin=Inches(.45);add_title(d,'Key descriptive findings | finance measures unavailable')
    d.add_heading('Four comparable indicators show improvement across 555 district matches',1);d.add_paragraph('From NFHS-4 to NFHS-5, average changes were +6.5 percentage points in women’s literacy, +6.3 in 10+ years of schooling, −3.8 in marriage before age 18, and +15.9 in clean cooking fuel. Changes are descriptive, not causal. Source: outputs/tables/district_changes.csv; n=555 per indicator.')
    d.add_heading('What is verified so far',2)
    table(d,['Data readiness measure','Value','Source'],[['Name-matched districts','555','Harvard Appendix A screen; district_crosswalk.csv'],['UP districts ranked','75','NFHS-5 four-indicator mean rank'],['ADP literacy difference','+1.99 pp','Descriptive; 95% bootstrap interval +0.76 to +3.14']])
    d.add_paragraph('The 130 changed/new geographies in Harvard Appendix A are excluded because a complete parent crosswalk is not available. Bank-account-use and mobile-phone indicators are absent from both factsheets, so no finance-linked index is reported.')
    d.add_page_break();d.add_heading('Three actions for a responsible district programme',1)
    bullet(d,'Use the 555 matched district results only with the stated boundary and indicator caveats; do not treat them as causal estimates.')
    bullet(d,'Treat Shrawasti, Lalitpur, Bahraich, Balrampur and Sitapur as provisional UP candidates from the four-indicator rank composite; validate financial access and service barriers before funding decisions.')
    bullet(d,'Measure independent use, transaction control, phone access and service reliability alongside account ownership.')
    d.add_picture(str(ROOT/'outputs'/'maps'/'women_literate_nfhs4.png'),width=Inches(5.4));p=d.add_paragraph('Interim map: NFHS-4 women literacy baseline only; 563 district geometries matched. It does not show change. Source and boundary note appear on the map.');p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p=d.add_paragraph('Kanishk Gupta | '+GITHUB);p.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    path=ROOT/'outputs'/'reports'/'ZilaLens_Policy_Brief.docx';d.save(path);return path

def deck():
    prs=Presentation();prs.slide_width=PInches(13.333);prs.slide_height=PInches(7.5)
    prs.core_properties.author=AUTHOR;prs.core_properties.title=TITLE+' | '+SUB;prs.core_properties.subject='Descriptive comparison; finance indicators unavailable'
    slides=[
      ('ZilaLens',SUB+'\nKanishk Gupta | '+GITHUB,'Interim edition, 18 October 2026.','title'),
      ('Four common indicators show district-level gains','Average matched changes: literacy +6.5 pp; schooling +6.3 pp; early marriage −3.8 pp; clean fuel +15.9 pp.','555 districts per indicator; source: outputs/tables/district_changes.csv. Descriptive changes, not causal effects.','text'),
      ('NFHS-4 provides a usable district baseline for selected indicators','59,241 district-indicator rows and 93 district indicators are present in the specified NFHS-4 compilation.','Source: HindustanTimesLabs nfhs_district-wise.csv and README. Counts describe the input file, not a population finding.','map1'),
      ('Improved sanitation varies across mapped districts at baseline','The interim map joins 563 district estimates to the available public district GeoJSON.','Source: NFHS-4 compilation and HindustanTimesLabs district GeoJSON. Boundary vintage is not confirmed as survey-equivalent.','map2'),
      ('Financial indicators are absent; a related-outcome typology is available','Bank-account use and women’s own mobile phone use are not available in these source files.','The finance-linked index is unavailable; a separate typology uses literacy, schooling, early marriage and clean-fuel levels and changes. Source: analysis_status.md.','text'),
      ('Changed geographies are screened before direct comparison','Harvard Appendix A lists 130 changed/new geography entries; 555 name-matched district IDs remain eligible.','The appendix lacks complete parent assignments. Those entries are excluded rather than imputed. See data/processed/harvard_changed_geographies.csv.','text'),
      ('The 112-district roster needs a reviewed NFHS crosswalk','The NITI 2022 roster has 112 entries; 96 match NFHS-4 state–district names exactly.','Sixteen names remain unresolved by exact matching; source list and project crosswalk are cited in the report. This is a roster coverage statistic, not an outcome estimate.','text'),
      ('UP ranking flags five districts for validation','The lowest five in the NFHS-5 four-indicator mean-rank composite are Shrawasti, Lalitpur, Bahraich, Balrampur and Sitapur.','All 75 UP districts ranked in outputs/tables/up_district_rankings.csv. Ghaziabad ranks 1; Gautam Buddha Nagar ranks 6.','mapup'),
      ('Policy documents point to reach, connectivity and delivery capacity','The PMJDY brochure describes branch and Bank Mitra reach and notes telecom constraints in some locations.','PMJDY Mission Document/Brochure, physical pp. 18, 20 and 30; NITI/UNDP ADP appraisal, physical pp. 15, 20 and 28. Paraphrases are in the coding matrix.','text'),
      ('The intervention should measure use and control alongside access','Proposed pathway: reachable service → women’s independent use → financial options → resilience.','The theory of change states assumptions. No programme effect is claimed.','toc'),
      ('Field validation can test whether ownership translates into use','The bilingual XLSForm asks about recent transactions, decision control, phone access, service failures, help needs and barriers.','Consent gate and skip logic are included; pyxform conversion succeeded without warnings.','text'),
      ('Five UP districts are provisional candidates for field validation','Shrawasti, Lalitpur, Bahraich, Balrampur and Sitapur rank lowest on the available four-indicator NFHS-5 composite.','Validate financial access, service barriers and boundary fit before final funding decisions. Aspirational contrasts are descriptive, not causal.','text'),
    ]
    for i,(title,body,note,visual) in enumerate(slides):
        s=prs.slides.add_slide(prs.slide_layouts[6]);bg=s.background.fill;bg.solid();bg.fore_color.rgb=PRGB(248,250,252)
        if i==0:
            box=s.shapes.add_textbox(PInches(.8),PInches(1.4),PInches(11.7),PInches(1.0));tf=box.text_frame;tf.text=title;tf.paragraphs[0].font.size=PPt(36);tf.paragraphs[0].font.bold=True;tf.paragraphs[0].font.color.rgb=PRGB(23,54,93)
            box=s.shapes.add_textbox(PInches(.8),PInches(2.55),PInches(10.8),PInches(1.6));tf=box.text_frame;tf.text=body;tf.paragraphs[0].font.size=PPt(19);tf.paragraphs[0].font.color.rgb=PRGB(22,140,140)
            add_footer(s,i+1);s.notes_slide.notes_text_frame.text=note;continue
        titlebox=s.shapes.add_textbox(PInches(.65),PInches(.4),PInches(12),PInches(1.0));p=titlebox.text_frame.paragraphs[0];p.text=title;p.font.size=PPt(26);p.font.bold=True;p.font.color.rgb=PRGB(23,54,93)
        bodybox=s.shapes.add_textbox(PInches(.8),PInches(1.65),PInches(11.7),PInches(2.0));p=bodybox.text_frame.paragraphs[0];p.text=body;p.font.size=PPt(23);p.font.color.rgb=PRGB(38,50,56)
        if visual.startswith('map'):
            img='women_literate_nfhs4.png' if visual=='map1' else ('women_literate_up_nfhs4.png' if visual=='mapup' else 'improved_sanitation_nfhs4.png')
            s.shapes.add_picture(str(ROOT/'outputs'/'maps'/img),PInches(8.0),PInches(3.05),height=PInches(3.8))
        elif visual=='toc':s.shapes.add_picture(str(ROOT/'outputs'/'charts'/'theory_of_change.png'),PInches(.9),PInches(3.3),width=PInches(11.6))
        if visual!='toc':
            noteBox=s.shapes.add_textbox(PInches(.8),PInches(5.9),PInches(6.6 if visual.startswith('map') else 11.7),PInches(.9));p=noteBox.text_frame.paragraphs[0];p.text=note;p.font.size=PPt(10);p.font.color.rgb=PRGB(91,101,115)
        add_footer(s,i+1);s.notes_slide.notes_text_frame.text=note
    path=ROOT/'outputs'/'deck'/'ZilaLens_Deck.pptx';prs.save(path);return path

def add_footer(slide,num):
    box=slide.shapes.add_textbox(PInches(.65),PInches(7.12),PInches(12),PInches(.2));p=box.text_frame.paragraphs[0];p.text=f'ZilaLens  |  Kanishk Gupta                                               {num:02d}';p.font.size=PPt(9);p.font.color.rgb=PRGB(91,101,115)

def build_all():
    (ROOT/'outputs'/'reports').mkdir(parents=True,exist_ok=True)
    report();concept_note();policy_brief();deck()

if __name__=='__main__':build_all()
